-- Contrôle : chaque cours porte désormais le texte relu.
do $ctl$
declare r record;
begin
  for r in
    select s.slug, s.titre
      from (values
        ($wb$comprendre-le-per-et-la-valorisation-a-la-brvm$wb$, $wb$Comprendre le PER et la valorisation à la BRVM$wb$),
        ($wb$etudes-de-cas-reels-brvm$wb$, $wb$Études de cas réels de la BRVM$wb$),
        ($wb$ipo-et-processus-brvm-cas-pratique-de-l-introduction-de-dang$wb$, $wb$L’introduction en bourse de Dangote : un cas pratique, hors BRVM$wb$),
        ($wb$suivi-dangote-brvm-ipo$wb$, $wb$Dangote et la BRVM : chronologie d’une introduction en bourse (2026)$wb$)
      ) as s(slug, titre)
      left join public.academy_courses c on c.slug = s.slug
     where c.slug is null or c.content->>'titre' is distinct from s.titre
  loop
    raise warning '0241 : cours % non mis à jour (absent, ou nombre de leçons différent de la sauvegarde)', r.slug;
  end loop;
end
$ctl$;
